const input = $input.first().json || {};
const query = input.query || {};
const body = input.body || {};

const rawMonthsBack = query.months_back ?? body.months_back ?? null;
let monthsBack = null;

if (rawMonthsBack !== null && rawMonthsBack !== undefined && rawMonthsBack !== '') {
  const parsed = parseInt(String(rawMonthsBack), 10);
  if (Number.isFinite(parsed) && parsed > 0 && parsed <= 24) {
    monthsBack = parsed;
  }
}

return {
  months_back: monthsBack,
  months_back_sql: monthsBack === null ? 'NULL' : String(monthsBack)
};

const rows = $input.all().map(item => item.json);

console.log(JSON.stringify({
  timestamp: new Date().toISOString(),
  route: 'cc_report/reset',
  event: 'cc_report_reset',
  total_rows: rows.length,
  level: 'info'
}));

return {
  statusCode: 201,
  body: { message: 'Status do CC Report resetado com sucesso' }
};

const errData = $input.first().json;

console.log(JSON.stringify({
  timestamp: new Date().toISOString(),
  route: 'cc_report/reset',
  event: 'db_error',
  message: errData.message || 'Erro desconhecido no banco',
  level: 'error'
}));

return {
  statusCode: 500,
  body: { ok: false, error: 'Erro de banco', message: 'Nao foi possivel resetar o status do cc report' }
};
